#include <atomic>
#include <vector>
#include <new>
#include <optional>
#include <cstddef>

template <class T>
class SpscRing {
public:
    explicit SpscRing(size_t cap_pow2)
        : cap_(cap_pow2), mask_(cap_pow2 - 1), buf_(cap_pow2) {
        // cap must be a power of two
    }

    // Producer side only.
    bool push(const T& v) {
        const size_t t = tail_.load(std::memory_order_relaxed);
        const size_t next = (t + 1) & mask_;
        if (next == cachedHead_) {                 // maybe full; refresh
            cachedHead_ = head_.load(std::memory_order_acquire);
            if (next == cachedHead_) return false; // truly full
        }
        buf_[t] = v;                               // 1) write payload
        tail_.store(next, std::memory_order_release); // 2) publish
        return true;
    }

    // Consumer side only.
    bool pop(T& out) {
        const size_t h = head_.load(std::memory_order_relaxed);
        if (h == cachedTail_) {                    // maybe empty; refresh
            cachedTail_ = tail_.load(std::memory_order_acquire);
            if (h == cachedTail_) return false;    // truly empty
        }
        out = buf_[h];                             // payload is visible (acquire above)
        head_.store((h + 1) & mask_, std::memory_order_release);
        return true;
    }

private:
    const size_t cap_, mask_;
    std::vector<T> buf_;
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
    alignas(64) size_t cachedHead_{0};   // producer-local
    size_t cachedTail_{0};               // consumer-local
};

SpscRing<MarketEvent> q(1 << 16);   // 65536 slots, mask = 0xFFFF

// Feed-handler thread (producer)
void feed_loop() {
    MarketEvent ev;
    while (read_from_nic(ev))
        while (!q.push(ev)) { /* full: spin or drop per policy */ }
}

// Strategy thread (consumer)
void strat_loop() {
    MarketEvent ev;
    while (running) {
        if (q.pop(ev)) on_event(ev);   // tens of ns handoff, no syscall
        // else busy-spin (optionally _mm_pause())
    }
}

template <class T>
class Spsc {
public:
    explicit Spsc(size_t n) : mask_(n - 1), buf_(n) { /* n must be pow2 */ }
    bool push(const T& v) {
        size_t t = tail_.load(std::memory_order_relaxed);
        size_t next = (t + 1) & mask_;
        if (next == cachedHead_ &&
            next == (cachedHead_ = head_.load(std::memory_order_acquire)))
            return false;                 // full
        buf_[t] = v;
        tail_.store(next, std::memory_order_release);
        return true;
    }
    bool pop(T& o) {
        size_t h = head_.load(std::memory_order_relaxed);
        if (h == cachedTail_ &&
            h == (cachedTail_ = tail_.load(std::memory_order_acquire)))
            return false;                 // empty
        o = buf_[h];
        head_.store((h + 1) & mask_, std::memory_order_release);
        return true;
    }
private:
    size_t mask_;
    std::vector<T> buf_;
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
    alignas(64) size_t cachedHead_{0};
    size_t cachedTail_{0};
};
